245	impl<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> Peer<E, C, T, B> {
246	    /// Encrypt and send a message to the peer
247	    ///
248	    /// Arguments:
249	    ///
250	    /// - `msg` : A padded vector holding the message (allows in-place construction of the transport header)
251	    /// - `stage`: Should the message be staged if no key is available
252	    pub(super) fn send(&self, msg: Vec<u8>, stage: bool) {
253	        // check if key available
254	        let (job, need_key) = {
255	            let mut enc_key = self.enc_key.lock();
256	            match enc_key.as_mut() {
257	                None => {
258	                    log::debug!("no key encryption key available");
259	                    if stage {
260	                        self.staged_packets.lock().push_back(msg);
261	                    };
262	                    (None, true)
263	                }
264	                Some(mut state) => {
265	                    // avoid integer overflow in nonce
266	                    if state.nonce >= REJECT_AFTER_MESSAGES - 1 {
267	                        log::debug!("encryption key expired");
268	                        *enc_key = None;
269	                        if stage {
270	                            self.staged_packets.lock().push_back(msg);
271	                        }
272	                        (None, true)
273	                    } else {
274	                        log::debug!("encryption state available, nonce = {}", state.nonce);
275	                        let job =
276	                            SendJob::new(msg, state.nonce, state.keypair.clone(), self.clone());
277	                        if self.outbound.push(job.clone()) {
278	                            state.nonce += 1;
279	                            (Some(job), false)
280	                        } else {
281	                            (None, false)
282	                        }
283	                    }
284	                }
285	            }
286	        };
287	
288	        if need_key {
289	            log::debug!("request new key");
290	            debug_assert!(job.is_none());
291	            C::need_key(&self.opaque);
292	        };
293	
294	        if let Some(job) = job {
295	            log::debug!("schedule outbound job");
296	            self.device.work.send(JobUnion::Outbound(job))
297	        }
298	    }
299	
300	    // Transmit all staged packets
301	    fn send_staged(&self) -> bool {
302	        log::trace!("peer.send_staged");
303	        let mut sent = false;
304	        let mut staged = self.staged_packets.lock();
305	        loop {
306	            match staged.pop_front() {
307	                Some(msg) => {
308	                    sent = true;
309	                    self.send(msg, false);
310	                }
311	                None => break sent,
312	            }
313	        }
314	    }
315	
316	    pub(super) fn confirm_key(&self, keypair: &Arc<KeyPair>) {
317	        log::trace!("peer.confirm_key");
318	        {
319	            // take lock and check keypair = keys.next
320	            let mut keys = self.keys.lock();
321	            let next = match keys.next.as_ref() {
322	                Some(next) => next,
323	                None => {
324	                    return;
325	                }
326	            };
327	            if !Arc::ptr_eq(&next, keypair) {
328	                return;
329	            }
330	
331	            // allocate new encryption state
332	            let ekey = Some(EncryptionState::new(&next));
333	
334	            // rotate key-wheel
335	            let mut swap = None;
336	            mem::swap(&mut keys.next, &mut swap);
337	            mem::swap(&mut keys.current, &mut swap);
338	            mem::swap(&mut keys.previous, &mut swap);
339	
340	            // tell the world outside the router that a key was confirmed
341	            C::key_confirmed(&self.opaque);
342	
343	            // set new key for encryption
344	            *self.enc_key.lock() = ekey;
345	        }
346	
347	        // start transmission of staged packets
348	        self.send_staged();
349	    }
350	}
